75	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
76	     * class.
77	     *
78	     * @param e     Object referring to the thrown exception.
79	     * @param status HTTP response status.
80	     * @param url URL request.
81	     */
82	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
83	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
84	        problemDetail.setType(URI.create(url.toString()));
85	        problemDetail.setTitle(e.getClass().getSimpleName());
86	        problemDetail.setDetail(detail);
87	        problemDetail.setProperty("timestamp", Instant.now());
88	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
